 1| /**
 2|  * Idempotency keys for POST and PATCH.
 3|  *
 4|  * A client may send `Idempotency-Key: <1-255 chars>`. For a given key:
 5|  * - first request: runs normally; a 2xx response is remembered (status, Location, Content-Type and
 6|  *   the exact serialized body, captured as it is sent, so a later change to the object the handler
 7|  *   sent, e.g. a PATCH that mutates the stored resource in place, cannot change the replay);
 8|  * - same method + path + body again: the remembered response is replayed byte for byte with
 9|  *   `Idempotent-Replayed: true` and the handler does not run;
10|  * - different method, path or body: 422 problem (idempotency-key-reuse);
11|  * - while the first request is still running: 409 problem (idempotency-key-in-flight).
12|  * Non-2xx responses are not remembered, so a corrected retry may reuse the key.
13|  */
14| import { createHash } from 'node:crypto';
15| import type { RequestHandler } from 'express';
16| import { z } from 'zod';
17| import { conflict, unprocessable } from './problem.ts';
18| 
19| export const IdempotencyHeadersSchema = z.object({
20|   'idempotency-key': z.string().min(1).max(255).optional(),
21| });
22| 
23| const StoredResponseSchema = z.discriminatedUnion('state', [
24|   z.object({ state: z.literal('in-flight'), fingerprint: z.string() }),
25|   z.object({
26|     state: z.literal('done'),
27|     fingerprint: z.string(),
28|     status: z.number().int(),
29|     location: z.string().optional(),
30|     contentType: z.string().optional(),
31|     /** The bytes sent (a JSON response is captured after serialization), or undefined for no body. */
32|     body: z.union([z.string(), z.instanceof(Buffer)]).optional(),
33|   }),
34| ]);
35| type StoredResponse = z.infer<typeof StoredResponseSchema>;
36| 
37| function fingerprint(method: string, path: string, body: unknown): string {
38|   return createHash('sha256').update(JSON.stringify([method, path, body ?? null])).digest('hex');
39| }
40| 
41| /** Middleware factory; each call owns its own key store (one per route). */
42| export function idempotency(): RequestHandler {
43|   const store = new Map<string, StoredResponse>();
44| 
45|   return (req, res, next) => {
46|     const key = IdempotencyHeadersSchema.parse(req.headers)['idempotency-key'];
47|     if (key === undefined) {
48|       next();
49|       return;
50|     }
51|     const print = fingerprint(req.method, req.originalUrl, req.body);
52|     const existing = store.get(key);
53|     if (existing !== undefined) {
54|       if (existing.fingerprint !== print) {
55|         throw unprocessable('Idempotency-Key was already used with a different request.', 'idempotency-key-reuse');
56|       }
57|       if (existing.state === 'in-flight') {
58|         throw conflict('A request with this Idempotency-Key is still being processed.', 'idempotency-key-in-flight');
59|       }
60|       res.status(existing.status).set('Idempotent-Replayed', 'true');
61|       if (existing.location !== undefined) res.location(existing.location);
62|       if (existing.contentType !== undefined) res.set('Content-Type', existing.contentType);
63|       if (existing.body === undefined) res.end();
64|       else res.send(existing.body);
65|       return;
66|     }
67| 
68|     store.set(key, StoredResponseSchema.parse({ state: 'in-flight', fingerprint: print }));
69|     const remember = (body: string | Buffer | undefined): void => {
70|       if (res.statusCode < 200 || res.statusCode > 299) return;
71|       const location = res.get('Location');
72|       const contentType = res.get('Content-Type');
73|       store.set(key, StoredResponseSchema.parse({ state: 'done', fingerprint: print, status: res.statusCode, location, contentType, body }));
74|     };
75|     // Remember the serialized response before it is sent, so a retry that races the socket still replays.
76|     // res.json (and res.send of an object) serialize and then call res.send with the string: capture that,
77|     // a snapshot no later mutation of the sent object can reach.
78|     const send = res.send.bind(res);
79|     res.send = (body?: unknown) => {
80|       if (typeof body === 'string') remember(body);
81|       else if (Buffer.isBuffer(body)) remember(Buffer.from(body));
82|       return send(body);
83|     };
84|     res.on('finish', () => {
85|       if (res.statusCode < 200 || res.statusCode > 299) store.delete(key);
86|       else if (store.get(key)?.state === 'in-flight') remember(undefined);
87|     });
88|     res.on('close', () => {
89|       if (store.get(key)?.state === 'in-flight') store.delete(key);
90|     });
91|     next();
92|   };
93| }

