import { randomUUID } from 'node:crypto';
import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app.ts';
import type { Express } from 'express';
import type { Label } from '../src/modules/labels/schema.ts';

describe('Labels', () => {
  let app: Express;

  beforeEach(() => {
    app = createApp();
  });

  const expectProblem = (res: any, status: number) => {
    expect(res.status).toBe(status);
    expect(res.type).toContain('application/problem+json');
    expect(res.body).toHaveProperty('type');
    expect(res.body).toHaveProperty('title');
    expect(res.body).toHaveProperty('status', status);
    expect(res.body).toHaveProperty('detail');
    expect(res.body).toHaveProperty('instance');
  };

  describe('POST /v1/labels', () => {
    it('creates a label with valid body and returns 201 with Location header', async () => {
      const res = await request(app).post('/v1/labels').send({ name: 'Bug', color: '#ff0000' });
      expect(res.status).toBe(201);
      expect(res.body).toHaveProperty('id');
      expect(res.body).toHaveProperty('name', 'Bug');
      expect(res.body).toHaveProperty('color', '#ff0000');
      expect(res.body).toHaveProperty('createdAt');
      expect(res.headers.location).toMatch(/^\/v1\/labels\/[a-f0-9-]+$/);
    });

    it('returns 422 for invalid name (empty)', async () => {
      const res = await request(app).post('/v1/labels').send({ name: '', color: '#ff0000' });
      expectProblem(res, 422);
      expect(res.body.detail).toContain('name');
    });

    it('returns 422 for invalid name (too long)', async () => {
      const res = await request(app).post('/v1/labels').send({ name: 'a'.repeat(41), color: '#ff0000' });
      expectProblem(res, 422);
      expect(res.body.detail).toContain('name');
    });

    it('returns 422 for invalid color (not hex)', async () => {
      const res = await request(app).post('/v1/labels').send({ name: 'Bug', color: 'red' });
      expectProblem(res, 422);
      expect(res.body.detail).toContain('color');
    });

    it('returns 422 for missing fields', async () => {
      const res = await request(app).post('/v1/labels').send({ name: 'Bug' });
      expectProblem(res, 422);
      expect(res.body.detail).toContain('color');
    });

    it('honours Idempotency-Key header', async () => {
      const key = randomUUID();
      const body = { name: 'Bug', color: '#ff0000' };
      const first = await request(app).post('/v1/labels').set('Idempotency-Key', key).send(body);
      const second = await request(app).post('/v1/labels').set('Idempotency-Key', key).send(body);
      expect(first.status).toBe(201);
      expect(second.status).toBe(201);
      expect(second.headers['idempotent-replayed']).toBe('true');
      expect(second.body).toEqual(first.body);
    });

    it('returns 409 conflict when Idempotency-Key is reused with different body', async () => {
      const key = randomUUID();
      await request(app).post('/v1/labels').set('Idempotency-Key', key).send({ name: 'Bug', color: '#ff0000' });
      const res = await request(app).post('/v1/labels').set('Idempotency-Key', key).send({ name: 'Feature', color: '#00ff00' });
      expect(res.status).toBe(409);
    });
  });

  describe('GET /v1/labels', () => {
    it('lists empty labels initially', async () => {
      const res = await request(app).get('/v1/labels');
      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('data');
      expect(res.body.data).toEqual([]);
      expect(res.body).toHaveProperty('nextCursor');
      expect(res.body.nextCursor).toBeNull();
    });

    it('lists created labels', async () => {
      await request(app).post('/v1/labels').send({ name: 'Bug', color: '#ff0000' });
      await request(app).post('/v1/labels').send({ name: 'Feature', color: '#00ff00' });
      const res = await request(app).get('/v1/labels');
      expect(res.status).toBe(200);
      expect(res.body.data).toHaveLength(2);
      expect(res.body.data[0]).toHaveProperty('id');
      expect(res.body.data[0]).toHaveProperty('name');
      expect(res.body.data[0]).toHaveProperty('color');
      expect(res.body.data[0]).toHaveProperty('createdAt');
    });

    it('supports cursor pagination with limit', async () => {
      const labels: Label[] = [];
      for (let i = 0; i < 5; i++) {
        const res = await request(app).post('/v1/labels').send({ name: `Label${i}`, color: '#000000' });
        labels.push(res.body);
      }

      const page1 = await request(app).get('/v1/labels?limit=2');
      expect(page1.status).toBe(200);
      expect(page1.body.data).toHaveLength(2);
      expect(page1.body.nextCursor).not.toBeNull();

      const page2 = await request(app).get(`/v1/labels?limit=2&cursor=${page1.body.nextCursor}`);
      expect(page2.status).toBe(200);
      expect(page2.body.data).toHaveLength(2);
      expect(page2.body.nextCursor).not.toBeNull();

      const page3 = await request(app).get(`/v1/labels?limit=2&cursor=${page2.body.nextCursor}`);
      expect(page3.status).toBe(200);
      expect(page3.body.data).toHaveLength(1);
      expect(page3.body.nextCursor).toBeNull();
    });

    it('visits every label exactly once following nextCursor', async () => {
      const created = [];
      for (let i = 0; i < 7; i++) {
        const res = await request(app).post('/v1/labels').send({ name: `Label${i}`, color: '#000000' });
        created.push(res.body.id);
      }

      const visited = new Set<string>();
      let cursor: string | null = null;
      let pageCount = 0;
      const maxPages = 20; // safety limit

      while (pageCount < maxPages) {
        const query = cursor ? `/v1/labels?limit=3&cursor=${cursor}` : '/v1/labels?limit=3';
        const res = await request(app).get(query);
        expect(res.status).toBe(200);

        for (const label of res.body.data) {
          expect(visited.has(label.id)).toBe(false); // should not have seen it before
          visited.add(label.id);
        }

        if (res.body.nextCursor === null) {
          break;
        }
        cursor = res.body.nextCursor;
        pageCount++;
      }

      expect(visited.size).toBe(created.length);
      for (const id of created) {
        expect(visited.has(id)).toBe(true);
      }
    });

    it('returns 422 for invalid cursor', async () => {
      const res = await request(app).get('/v1/labels?cursor=invalid');
      expectProblem(res, 422);
    });

    it('returns 422 for invalid limit', async () => {
      const res = await request(app).get('/v1/labels?limit=abc');
      expectProblem(res, 422);
    });
  });

  describe('GET /v1/labels/{labelId}', () => {
    it('returns the label for a valid id', async () => {
      const created = await request(app).post('/v1/labels').send({ name: 'Bug', color: '#ff0000' });
      const res = await request(app).get(`/v1/labels/${created.body.id}`);
      expect(res.status).toBe(200);
      expect(res.body).toEqual(created.body);
    });

    it('returns 404 for unknown id', async () => {
      const unknownId = randomUUID();
      const res = await request(app).get(`/v1/labels/${unknownId}`);
      expectProblem(res, 404);
      expect(res.body.detail).toContain('not found');
    });

    it('returns 422 for malformed id', async () => {
      const res = await request(app).get('/v1/labels/not-a-uuid');
      expectProblem(res, 422);
    });
  });

  describe('Existing routes', () => {
    it('keeps GET /v1/projects working', async () => {
      const res = await request(app).get('/v1/projects');
      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('data');
      expect(res.body).toHaveProperty('nextCursor');
    });

    it('keeps POST /v1/projects working', async () => {
      const res = await request(app).post('/v1/projects').send({ name: 'Test', description: 'Test' });
      expect(res.status).toBe(201);
      expect(res.body).toHaveProperty('id');
      expect(res.body).toHaveProperty('name', 'Test');
    });
  });
});

import { randomUUID } from 'node:crypto';
import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import type { Express } from 'express';
import { createApp } from '../src/app.ts';
import type { Label } from '../src/modules/labels/schema.ts';
import type { Problem } from '../src/lib/problem.ts';

let app: Express;

beforeEach(() => {
  app = createApp();
});

function isProblem(obj: unknown): obj is Problem {
  return (
    typeof obj === 'object' &&
    obj !== null &&
    'type' in obj &&
    'title' in obj &&
    'status' in obj &&
    typeof (obj as Record<string, unknown>).type === 'string' &&
    typeof (obj as Record<string, unknown>).title === 'string' &&
    typeof (obj as Record<string, unknown>).status === 'number'
  );
}

function expectProblem(response: { body: unknown }, status: number): void {
  expect(response.body).toSatisfy((body: unknown) => isProblem(body));
  const prob = response.body as Problem;
  expect(prob.status).toBe(status);
}

async function createLabel(body: { name: string; color: string }): Promise<Label> {
  const res = await request(app).post('/v1/labels').send(body);
  expect(res.status).toBe(201);
  const label = res.body as Label;
  expect(label.id).toBeDefined();
  expect(label.name).toBe(body.name);
  expect(label.color).toBe(body.color);
  expect(label.createdAt).toBeDefined();
  return label;
}

describe('Labels', () => {
  it('POST /v1/labels with valid body returns 201, label, and Location header', async () => {
    const res = await request(app).post('/v1/labels').send({ name: 'bug', color: '#ff0000' });
    expect(res.status).toBe(201);
    const label = res.body as Label;
    expect(label).toHaveProperty('id');
    expect(label).toHaveProperty('name', 'bug');
    expect(label).toHaveProperty('color', '#ff0000');
    expect(label).toHaveProperty('createdAt');
    expect(res.headers.location).toBe(`/v1/labels/${label.id}`);
  });

  it('POST /v1/labels with invalid name returns 422 problem', async () => {
    const res = await request(app).post('/v1/labels').send({ name: '', color: '#ff0000' });
    expect(res.status).toBe(422);
    expectProblem(res, 422);
    const prob = res.body as Problem;
    expect(prob.detail).toContain('name');
  });

  it('POST /v1/labels with name too long returns 422 problem', async () => {
    const res = await request(app).post('/v1/labels').send({ name: 'x'.repeat(41), color: '#ff0000' });
    expect(res.status).toBe(422);
    expectProblem(res, 422);
    const prob = res.body as Problem;
    expect(prob.detail).toContain('name');
  });

  it('POST /v1/labels with invalid color returns 422 problem', async () => {
    const res = await request(app).post('/v1/labels').send({ name: 'bug', color: 'red' });
    expect(res.status).toBe(422);
    expectProblem(res, 422);
    const prob = res.body as Problem;
    expect(prob.detail).toContain('color');
  });

  it('POST /v1/labels with multiple invalid fields returns 422 naming each field', async () => {
    const res = await request(app).post('/v1/labels').send({ name: '', color: 'invalid' });
    expect(res.status).toBe(422);
    expectProblem(res, 422);
    const prob = res.body as Problem;
    expect(prob.detail).toContain('name');
    expect(prob.detail).toContain('color');
  });

  it('POST /v1/labels repeated with same Idempotency-Key replays response and creates no second label', async () => {
    const key = randomUUID();
    const first = await request(app).post('/v1/labels').set('Idempotency-Key', key).send({ name: 'bug', color: '#ff0000' });
    expect(first.status).toBe(201);
    const firstLabel = first.body as Label;

    const second = await request(app).post('/v1/labels').set('Idempotency-Key', key).send({ name: 'bug', color: '#ff0000' });
    expect(second.status).toBe(201);
    expect(second.headers['idempotent-replayed']).toBe('true');
    expect(second.body).toEqual(first.body);

    // Verify only one label was created
    const list = await request(app).get('/v1/labels');
    const data = (list.body as { data: Label[] }).data;
    const bugsCount = data.filter((l) => l.name === 'bug').length;
    expect(bugsCount).toBe(1);
  });

  it('GET /v1/labels lists labels with cursor pagination', async () => {
    const label1 = await createLabel({ name: 'bug', color: '#ff0000' });
    const label2 = await createLabel({ name: 'feature', color: '#00ff00' });
    const label3 = await createLabel({ name: 'docs', color: '#0000ff' });

    const page1 = await request(app).get('/v1/labels?limit=2');
    expect(page1.status).toBe(200);
    const body1 = page1.body as { data: Label[]; nextCursor: string | null };
    expect(body1.data).toHaveLength(2);
    expect(body1.nextCursor).toBeDefined();

    const page2 = await request(app).get(`/v1/labels?cursor=${body1.nextCursor as string}&limit=2`);
    expect(page2.status).toBe(200);
    const body2 = page2.body as { data: Label[]; nextCursor: string | null };
    expect(body2.data).toHaveLength(1);
    expect(body2.nextCursor).toBeNull();

    const allIds = new Set([...body1.data, ...body2.data].map((l) => l.id));
    expect(allIds.size).toBe(3);
    expect(allIds.has(label1.id)).toBe(true);
    expect(allIds.has(label2.id)).toBe(true);
    expect(allIds.has(label3.id)).toBe(true);
  });

  it('GET /v1/labels/{labelId} returns the label', async () => {
    const label = await createLabel({ name: 'bug', color: '#ff0000' });
    const res = await request(app).get(`/v1/labels/${label.id}`);
    expect(res.status).toBe(200);
    expect(res.body).toEqual(label);
  });

  it('GET /v1/labels/{labelId} with unknown id returns 404 problem', async () => {
    const unknownId = randomUUID();
    const res = await request(app).get(`/v1/labels/${unknownId}`);
    expect(res.status).toBe(404);
    expectProblem(res, 404);
  });

  it('GET /v1/labels/{labelId} with malformed id returns 422 problem', async () => {
    const res = await request(app).get('/v1/labels/not-a-uuid');
    expect(res.status).toBe(422);
    expectProblem(res, 422);
  });

  it('existing project routes still work', async () => {
    const projRes = await request(app).post('/v1/projects').send({ name: 'My Project' });
    expect(projRes.status).toBe(201);
    const project = projRes.body as Record<string, unknown>;
    expect(project).toHaveProperty('id');
    expect(project).toHaveProperty('name', 'My Project');
  });
});

import { randomUUID } from 'node:crypto';
import { paginate } from '../../lib/pagination.ts';
import type { CreateLabel, ListLabelsQuery, Label, LabelPage } from './schema.ts';

const labels = new Map<string, Label>();

const sortKey = (label: Label): string => `${label.createdAt}|${label.id}`;

export function listLabels(query: ListLabelsQuery): LabelPage {
  return paginate(Array.from(labels.values()), query, sortKey);
}

export function getLabel(id: string): Label | undefined {
  return labels.get(id);
}

export function createLabel(input: CreateLabel): Label {
  const id = randomUUID();
  const createdAt = new Date().toISOString();
  const label: Label = { id, ...input, createdAt };
  labels.set(id, label);
  return label;
}

export function labelIdempotencyKey(input: CreateLabel): string {
  return `${input.name}|${input.color}`;
}

