import { z } from 'zod';
import { CursorQuerySchema, pageSchema } from '../../lib/pagination.ts';

export const LabelSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(1, 'name must be 1-40 characters').max(40, 'name must be 1-40 characters'),
  color: z.string().regex(/^#[0-9a-f]{6}$/i, 'color must be a hex string like "#1a2b3c"'),
  createdAt: z.string().datetime(),
});

export type Label = z.infer<typeof LabelSchema>;

export const LabelParamsSchema = z.object({ labelId: z.string().uuid() });

export const CreateLabelSchema = z.strictObject({
  name: z.string().min(1, 'name must be 1-40 characters').max(40, 'name must be 1-40 characters'),
  color: z.string().regex(/^#[0-9a-f]{6}$/i, 'color must be a hex string like "#1a2b3c"'),
});

export type CreateLabel = z.infer<typeof CreateLabelSchema>;

export const ListLabelsQuerySchema = CursorQuerySchema;
export type ListLabelsQuery = z.infer<typeof ListLabelsQuerySchema>;

export const LabelPageSchema = pageSchema(LabelSchema);
export type LabelPage = z.infer<typeof LabelPageSchema>;

import { randomUUID } from 'node:crypto';
import { paginate } from '../../lib/pagination.ts';
import type { CreateLabel, ListLabelsQuery, Label, LabelPage } from './schema.ts';

const labels = new Map<string, Label>();

const sortKey = (label: Label): string => `${label.createdAt}|${label.id}`;

export function listLabels(query: ListLabelsQuery): LabelPage {
  return paginate(Array.from(labels.values()), query, sortKey);
}

export function getLabel(id: string): Label | undefined {
  return labels.get(id);
}

export function createLabel(input: CreateLabel): Label {
  const id = randomUUID();
  const createdAt = new Date().toISOString();
  const label: Label = { id, ...input, createdAt };
  labels.set(id, label);
  return label;
}

export function labelExists(id: string): boolean {
  return labels.has(id);
}

