import { Router } from 'express';
import { idempotency } from '../../lib/idempotency.ts';
import { notFound, unprocessable } from '../../lib/problem.ts';
import {
  LabelParamsSchema,
  CreateLabelSchema,
  ListLabelsQuerySchema,
} from './schema.ts';
import { createLabel, getLabel, listLabels } from './store.ts';

export const labelsRouter = Router();

labelsRouter.get('/v1/labels', (req, res) => {
  const query = ListLabelsQuerySchema.parse(req.query);
  const page = listLabels(query);
  res.json(page);
});

labelsRouter.post('/v1/labels', idempotency(), (req, res) => {
  const input = CreateLabelSchema.parse(req.body);
  const label = createLabel(input);
  res.status(201).location(`/v1/labels/${label.id}`).json(label);
});

labelsRouter.get('/v1/labels/:labelId', (req, res) => {
  const params = LabelParamsSchema.parse(req.params);
  const label = getLabel(params.labelId);
  if (!label) {
    throw notFound(`Label with id ${params.labelId} not found`);
  }
  res.json(label);
});

