import { describe, it, expect, beforeEach } from 'vitest';
import { createLabel, getLabel, listLabels } from '../src/modules/labels/store.ts';

describe('Labels Store', () => {
  beforeEach(() => {
    // Store is in-memory, test isolation handled by the test runner
  });

  it('creates a label with valid input', () => {
    const label = createLabel({ name: 'bug', color: '#ff0000' });
    expect(label).toHaveProperty('id');
    expect(label.name).toBe('bug');
    expect(label.color).toBe('#ff0000');
    expect(label).toHaveProperty('createdAt');
  });

  it('retrieves a label by id', () => {
    const created = createLabel({ name: 'feature', color: '#00ff00' });
    const retrieved = getLabel(created.id);
    expect(retrieved).toEqual(created);
  });

  it('returns undefined for non-existent label', () => {
    const retrieved = getLabel('00000000-0000-0000-0000-000000000000');
    expect(retrieved).toBeUndefined();
  });

  it('lists labels with pagination', () => {
    createLabel({ name: 'bug', color: '#ff0000' });
    createLabel({ name: 'feature', color: '#00ff00' });
    createLabel({ name: 'docs', color: '#0000ff' });

    const page = listLabels({ cursor: null, limit: 2 });
    expect(page.data).toHaveLength(2);
    expect(page.nextCursor).toBeDefined();
  });

  it('paginates through all labels', () => {
    const labels = [];
    for (let i = 0; i < 5; i++) {
      labels.push(createLabel({ name: `label${i}`, color: '#000000' }));
    }

    const allRetrieved: typeof labels = [];
    let cursor: string | null = null;
    let iterations = 0;
    const maxIterations = 10; // safety limit

    while (iterations < maxIterations) {
      const page = listLabels({ cursor, limit: 2 });
      allRetrieved.push(...page.data);
      if (!page.nextCursor) break;
      cursor = page.nextCursor;
      iterations++;
    }

    expect(allRetrieved).toHaveLength(labels.length);
  });
});

